<script setup>import {useForm} from '@inertiajs/vue3';import {store as contactStore} from '../actions/App/Http/Controllers/ContactController';import PublicLayout from '../Layouts/PublicLayout.vue';const form=useForm({name:'',email:'',topic:'course',message:''});function submit(){form.post(contactStore().url,{preserveScroll:true,onSuccess:()=>form.reset()})}</script>
<template><PublicLayout><main class="public-page"><section class="page-hero wrap"><div class="eyebrow">WE’RE HERE TO HELP</div><h1>Let’s find your<br><em>next good thing.</em></h1><p>Ask us about a course, a cohort schedule, or whether a program is right for you.</p></section><section class="wrap page-content contact-layout"><form class="contact-form" @submit.prevent="submit"><label>Your name<input v-model="form.name" required autocomplete="name"><small v-if="form.errors.name">{{form.errors.name}}</small></label><label>Email address<input v-model="form.email" type="email" required autocomplete="email"><small v-if="form.errors.email">{{form.errors.email}}</small></label><label>What can we help with?<select v-model="form.topic"><option value="course">Choosing a course</option><option value="team">Team learning</option><option value="other">Something else</option></select></label><label>Your message<textarea v-model="form.message" rows="6" minlength="20" maxlength="5000" required placeholder="Tell us a little about what you’re looking for…"></textarea><small v-if="form.errors.message">{{form.errors.message}}</small></label><button class="button button-dark" :disabled="form.processing">{{form.processing?'Sending…':'Send your message'}} <UiIcon v-if="!form.processing" name="arrow-up-right" class="ui-icon" :size="13" /></button></form><aside class="contact-aside"><div class="eyebrow">A HUMAN WILL REPLY</div><h2>Tell us where you want to go.</h2><p>We’ll help you compare programs, understand the live schedule, and decide what makes sense for you.</p><p><b>Course questions</b><br>We can help you find a good fit before you enroll.</p><p><b>Team learning</b><br>Let’s talk about a cohort for your team.</p></aside></section></main></PublicLayout></template>
